/* node builds/bundle.js
 *
 * The page opens builds by name: play.html?build=test-all. A browser will
 * not fetch a local .json file from a page opened as a file (file://), so
 * this writes every builds/*.json into builds/builds.js, which the page
 * loads with a script tag. Run it after adding or editing a build; fxcheck.js
 * fails when builds.js is out of date with the .json files.
 */
'use strict';
var fs = require('fs'), path = require('path');
function bundle() {
  var here = __dirname, all = {};
  fs.readdirSync(here).filter(function (f) { return /\.json$/.test(f); }).sort().forEach(function (f) {
    all[f.replace(/\.json$/, '')] = JSON.parse(fs.readFileSync(path.join(here, f), 'utf8'));
  });
  return '/* generated by builds/bundle.js from builds/*.json; do not edit */\n' +
    'window.KMBUILDS = ' + JSON.stringify(all, null, 1) + ';\n';
}
if (require.main === module) {
  fs.writeFileSync(path.join(__dirname, 'builds.js'), bundle());
  console.log('builds.js written');
}
module.exports = { bundle: bundle };
